  const url = new URL(req.url ?? '/', 'http://localhost');
  const path = url.pathname;
  const method = req.method ?? 'GET';

  let allowed: string[];
  if (path === '/' || path === '/health') allowed = ['GET'];
  else if (path === '/api/jobs') allowed = ['GET', 'POST'];
  else if (/^\/api\/jobs\/[^/]+$/.test(path)) allowed = ['GET'];
  else return sendError(res, 404, 'not_found', 'No such route.');

  if (!allowed.includes(method)) {
    return sendError(res, 405, 'method_not_allowed', `${method} is not allowed on this route.`, undefined);
  }

  if (path === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    return void res.end(uiHtml);
  }
  if (path === '/health') return handleHealth(res);
  if (path === '/api/jobs') {
    if (method === 'POST') return handleCreateJob(req, res);
    return send(res, 200, { jobs: listJobs(db).map(toJob) });
  }
  return handleGetJob(res, decodeURIComponent(path.slice('/api/jobs/'.length)));
