import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import {
  getJobById,
  getJobByKey,
  insertJob,
  lastHeartbeat,
  listJobs,
  openDatabase,
  transaction,
  type JobRow,
} from './db.ts';

const MAX_BODY_BYTES = 64 * 1024;
const WORKER_LIVENESS_MS = 3000;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const DEFAULT_STEPS = 5;
const DEFAULT_FAIL_ATTEMPTS = 0;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

interface FieldError {
  field: string;
  message: string;
}

interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function invalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

function toJob(r: JobRow) {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.progress_completed, total: r.steps },
    result: r.status === 'completed' ? { output: r.result_output } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

/** Reads the whole body; resolves to null if it exceeds the size limit. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      if (tooLarge) return;
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        resolve(null);
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      if (!tooLarge) resolve(Buffer.concat(chunks).toString('utf8'));
    });
    req.on('error', reject);
  });
}

function isJsonContentType(header: string | undefined): boolean {
  if (!header) return false;
  return header.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

/** Validates a parsed body. Returns the job to create (defaults applied) or the offending fields. */
function validateBody(raw: string): { ok: true; job: NewJob } | { ok: false; fields: FieldError[] } {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return { ok: false, fields: [{ field: 'body', message: 'Body must be valid JSON.' }] };
  }
  if (!isObject(parsed)) return { ok: false, fields: [{ field: 'body', message: 'Body must be a JSON object.' }] };

  const fields: FieldError[] = [];
  const allowed = new Set(['input', 'steps', 'failAttempts']);
  for (const key of Object.keys(parsed)) {
    if (!allowed.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  const { input, steps = DEFAULT_STEPS, failAttempts = DEFAULT_FAIL_ATTEMPTS } = parsed;
  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'input is required and must be a string.' });
  } else if (input.length < 1 || input.length > 1000 || input.trim().length === 0) {
    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters and not only whitespace.' });
  }
  if (!Number.isInteger(steps) || (steps as number) < 1 || (steps as number) > 20) {
    fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20.' });
  }
  if (!Number.isInteger(failAttempts) || (failAttempts as number) < 0 || (failAttempts as number) > 5) {
    fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5.' });
  }

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, job: { input: input as string, steps: steps as number, failAttempts: failAttempts as number } };
}

function sameJob(row: JobRow, job: NewJob): boolean {
  return row.input === job.input && row.steps === job.steps && row.fail_attempts === job.failAttempts;
}

