  if (raw === null) {
    return invalid(res, [...keyFields, { field: 'body', message: 'Body is too large.' }]);
  }
  if (!isJsonContentType(req.headers['content-type'])) {
    return invalid(res, [...keyFields, { field: 'body', message: 'Content-Type must be application/json.' }]);
  }
  const result = validateBody(raw);
  if (!result.ok) return invalid(res, [...keyFields, ...result.fields]);
  if (keyFields.length > 0) return invalid(res, keyFields);

  const job = result.job;
