    if (key !== undefined) {
      const existing = getJobByKey(db, key);
      if (existing) return sameJob(existing, job) ? { replay: existing } : { conflict: true as const };
    }
    return { created: insertJob(db, { id: randomUUID(), ...job, idempotencyKey: key ?? null }) };
  });

