import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import {
  getJobById,
  getJobByKey,
  insertJob,
  lastHeartbeat,
  listJobs,
  openDatabase,
  transaction,
  type JobRow,
} from './db.ts';

const MAX_BODY_BYTES = 64 * 1024;
const WORKER_LIVENESS_MS = 3000;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const DEFAULT_STEPS = 5;
const DEFAULT_FAIL_ATTEMPTS = 0;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

interface FieldError {
  field: string;
  message: string;
}

interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function invalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

function toJob(r: JobRow) {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.progress_completed, total: r.steps },
    result: r.status === 'completed' ? { output: r.result_output } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

/** Reads the whole body; resolves to null if it exceeds the size limit. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      if (tooLarge) return;
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        resolve(null);
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      if (!tooLarge) resolve(Buffer.concat(chunks).toString('utf8'));
    });
    req.on('error', reject);
  });
}

function isJsonContentType(header: string | undefined): boolean {
  if (!header) return false;
  return header.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

/** Validates a parsed body. Returns the job to create (defaults applied) or the offending fields. */
function validateBody(raw: string): { ok: true; job: NewJob } | { ok: false; fields: FieldError[] } {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return { ok: false, fields: [{ field: 'body', message: 'Body must be valid JSON.' }] };
  }
  if (!isObject(parsed)) return { ok: false, fields: [{ field: 'body', message: 'Body must be a JSON object.' }] };

  const fields: FieldError[] = [];
  const allowed = new Set(['input', 'steps', 'failAttempts']);
  for (const key of Object.keys(parsed)) {
    if (!allowed.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  const { input, steps = DEFAULT_STEPS, failAttempts = DEFAULT_FAIL_ATTEMPTS } = parsed;
  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'input is required and must be a string.' });
  } else if (input.length < 1 || input.length > 1000 || input.trim().length === 0) {
    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters and not only whitespace.' });
  }
  if (!Number.isInteger(steps) || (steps as number) < 1 || (steps as number) > 20) {
    fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20.' });
  }
  if (!Number.isInteger(failAttempts) || (failAttempts as number) < 0 || (failAttempts as number) > 5) {
    fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5.' });
  }

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, job: { input: input as string, steps: steps as number, failAttempts: failAttempts as number } };
}

function sameJob(row: JobRow, job: NewJob): boolean {
  return row.input === job.input && row.steps === job.steps && row.fail_attempts === job.failAttempts;
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const rawKey = req.headers['idempotency-key'];
  const key = rawKey === undefined ? undefined : String(rawKey);
  const keyFields: FieldError[] = [];
  if (key !== undefined && !IDEMPOTENCY_KEY_RE.test(key)) {
    keyFields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  const raw = await readBody(req);
  if (raw === null) {
    return invalid(res, [...keyFields, { field: 'body', message: 'Body is too large.' }]);
  }
  if (!isJsonContentType(req.headers['content-type'])) {
    return invalid(res, [...keyFields, { field: 'body', message: 'Content-Type must be application/json.' }]);
  }
  const result = validateBody(raw);
  if (!result.ok) return invalid(res, [...keyFields, ...result.fields]);
  if (keyFields.length > 0) return invalid(res, keyFields);

  const job = result.job;
  type Outcome = { kind: 'created' | 'replay' | 'conflict'; row?: JobRow };
  const outcome: Outcome = transaction(db, (): Outcome => {
    if (key !== undefined) {
      const existing = getJobByKey(db, key);
      if (existing) return sameJob(existing, job) ? { kind: 'replay', row: existing } : { kind: 'conflict' };
    }
    return { kind: 'created', row: insertJob(db, { id: randomUUID(), ...job, idempotencyKey: key ?? null }) };
  });

  if (outcome.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.kind === 'replay' ? 200 : 201, toJob(outcome.row!));
}

function handleGetJob(res: ServerResponse, id: string): void {
  const row = getJobById(db, id);
  if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
  send(res, 200, toJob(row));
}

function handleHealth(res: ServerResponse): void {
  const beat = lastHeartbeat(db);
  const up = beat !== undefined && Date.now() - beat <= WORKER_LIVENESS_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const path = url.pathname;
  const method = req.method ?? 'GET';

  let allowed: string[];
  if (path === '/' || path === '/health') allowed = ['GET'];
  else if (path === '/api/jobs') allowed = ['GET', 'POST'];
  else if (/^\/api\/jobs\/[^/]+$/.test(path)) allowed = ['GET'];
  else return sendError(res, 404, 'not_found', 'No such route.');

  if (!allowed.includes(method)) {
    res.setHeader('allow', allowed.join(', '));
    return sendError(res, 405, 'method_not_allowed', `${method} is not allowed on this route.`);
  }

  if (path === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    return void res.end(uiHtml);
  }
  if (path === '/health') return handleHealth(res);
  if (path === '/api/jobs') {
    if (method === 'POST') return handleCreateJob(req, res);
    return send(res, 200, { jobs: listJobs(db).map(toJob) });
  }
  let id: string;
  try {
    id = decodeURIComponent(path.slice('/api/jobs/'.length));
  } catch {
    return sendError(res, 404, 'not_found', 'No job with that id.');
  }
  return handleGetJob(res, id);
}

const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request error:', e instanceof Error ? e.message : e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 2000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
